//! J24I35 research-only falsifier: CMA4 CRC-only mutation vs SHA-valid native verify.
//! Source-exact original r24 symlink and mutation are generated by installed Python.
//! Deliberately ignored in normal Cargo tests: the dedicated CI must supply physical specimens.
//! Do not turn an expected integrity false positive into a product PASS claim.
use cmpct_core::{Archive, CmpctError};
use std::env;
use std::path::PathBuf;

fn case_path(stem: &str) -> PathBuf {
    PathBuf::from(env::var("J24I35_CASE_DIR").expect("dedicated CI must set J24I35_CASE_DIR"))
        .join(format!("{stem}.cmpct"))
}

#[test]
#[ignore = "requires source-exact installed r24 specimens"]
fn j24i35_same_bytes_sha_valid_crc_altered_scientific_falsifier() {
    let genuine = Archive::open(&case_path("original")).expect("real r24 symlink must open");
    assert_eq!(genuine.entries().len(), 1);
    assert_eq!(genuine.entries()[0].kind, 2);
    assert_eq!(genuine.verify_complete().expect("genuine SHA-valid archive"), 1);
    println!("J24I35_GENUINE:verified_payload_count=1");

    let crc_only = Archive::open(&case_path("crc-wrong"))
        .expect("CRC-only altered record must remain index-parseable");
    // Prediction under test: native strong verifier binds decoded SHA-256
    // but does not check separately recorded CMA4 CRC32.
    match crc_only.verify_complete() {
        Ok(1) => println!("J24I35_NATIVE_CRC_MISMATCH_ACCEPTED:verified_payload_count=1"),
        Ok(count) => panic!("unexpected payload count {count}: expected exactly 1"),
        Err(other) => panic!("prediction falsified: native refused CRC-only mismatch: {other}"),
    }

    let payload_wrong = Archive::open(&case_path("physical-wrong"))
        .expect("original J24I30 payload-corrupt control must remain parseable");
    match payload_wrong.verify_complete() {
        Err(CmpctError::MemberHash) => println!("J24I35_PHYSICAL_PAYLOAD_REJECTED:MemberHash"),
        Err(other) => panic!("SHA control failed differently: {other}"),
        Ok(count) => panic!("false strong-verification pass after {count} entries"),
    }
}
